import os
import unittest
from unittest.mock import patch

from diskcache import Cache

import bencher as bn
from bencher.bench_plot_server import (
    _DEVPOD_PORT_MAX,
    _DEVPOD_PORT_MIN,
    _PORT_RANGE_MAX,
    _PORT_RANGE_MIN,
    _candidate_ports,
)
from bencher.example.benchmark_data import SimpleBenchClass


class TestBenchPlotServer(unittest.TestCase):
    # Tests that the plot server loads previously calculated benchmark data from the database
    def test_plot_server_load_data_from_database(self):
        sbc = SimpleBenchClass()
        bench = bn.Bench("test_bench_server", sbc)
        bench.plot_sweep(
            title="test_bench_server",
            input_vars=[sbc.param.var1],
            result_vars=[sbc.param.result],
            run_cfg=bn.BenchRunCfg(auto_plot=False),
        )
        bench.report.save()

        bps = bn.BenchPlotServer()

        server_cfg = bn.BenchRunCfg()
        server_cfg.show = False

        server = bps.plot_server(bench.bench_name, server_cfg)
        server.stop()

    # Tests that the plot server raises FileNotFoundError when no data is found in the cache
    def test_plot_server_no_data_in_cache(self):
        server = bn.BenchPlotServer()
        bench_name = "test_bench"
        with self.assertRaises(FileNotFoundError):
            server.load_data_from_cache(bench_name)

    # Tests that the plot server raises FileNotFoundError when no data is found in the database
    def test_plot_server_no_data_in_database(self):
        server = bn.BenchPlotServer()
        bench_name = "test_bench"
        with Cache("cachedir/benchmark_inputs") as cache:
            if bench_name in cache:
                with self.assertRaises(FileNotFoundError):
                    server.load_data_from_cache(bench_name)
            else:
                with self.assertRaises(FileNotFoundError):
                    server.load_data_from_cache(bench_name)

    def test_plot_server_port(self):
        bps = bn.BenchPlotServer()
        server_cfg = bn.BenchRunCfg()
        server_cfg.port = 34343
        server_cfg.show = False
        srv = bps.plot_server("test_bench_server", server_cfg)
        srv.stop()

    def test_serve_auto_port(self):
        """When no port is specified, the server should bind to an OS-assigned port."""
        import panel as pn

        bps = bn.BenchPlotServer()
        plots = pn.Column("# test")
        srv = bps.serve("auto_port_test", plots, port=None, show=False)
        srv.stop()

    def test_serve_parallel_no_port_conflict(self):
        """Two servers with port=None must not raise OSError: Address already in use."""
        import panel as pn

        bps = bn.BenchPlotServer()
        srv1 = bps.serve("parallel_1", pn.Column("# a"), port=None, show=False)
        srv2 = bps.serve("parallel_2", pn.Column("# b"), port=None, show=False)
        srv2.stop()
        srv1.stop()

    def test_serve_auto_port_is_forwardable_in_devpod(self):
        """DevPod only discovers low listening ports, so its workspace id selects one."""
        import panel as pn

        bps = bn.BenchPlotServer()
        with (
            patch.dict(os.environ, {"DEVPOD_WORKSPACE_ID": "bencher-feature-a"}),
            patch("bencher.bench_plot_server.pn.serve") as serve,
        ):
            bps.serve("devpod_port", pn.Column("# test"), port=None, show=False)
        port = serve.call_args.kwargs["port"]
        self.assertGreaterEqual(port, _DEVPOD_PORT_MIN)
        self.assertLessEqual(port, _DEVPOD_PORT_MAX)
        self.assertNotEqual(port, 10800)

    def test_devpod_workspace_port_is_stable(self):
        """The same workspace must land on the same port across restarts."""
        with patch.dict(os.environ, {"DEVPOD_WORKSPACE_ID": "bencher-feature-a"}):
            first = next(_candidate_ports())
            second = next(_candidate_ports())
        self.assertEqual(first, second)

    def test_devpod_workspaces_do_not_share_a_port(self):
        """Two workspaces serving reports at once must not fight over one port."""
        with patch.dict(os.environ, {"DEVPOD_WORKSPACE_ID": "bencher-feature-a"}):
            first = next(_candidate_ports())
        with patch.dict(os.environ, {"DEVPOD_WORKSPACE_ID": "bencher-feature-b"}):
            second = next(_candidate_ports())
        self.assertNotEqual(first, second)

    def test_auto_port_outside_devpod_stays_in_the_dynamic_range(self):
        with patch.dict(os.environ, {}, clear=True):
            ports = list(_candidate_ports())
        self.assertTrue(all(_PORT_RANGE_MIN <= port <= _PORT_RANGE_MAX for port in ports), ports)
